540	            textStr = textStr.replaceAll("&quot;", "\"");
541	            textStr = textStr.replaceAll("&copy;", "");
542	            textStr = textStr.replaceAll("&apos;", "'");
543	
544	            int skipCount = 0;
545	            for (int i = 0; i < textStr.length(); i++) {
546	                String text = textStr.substring(i, i + 1);
547	                boolean skipPosition = false;
548	                if (i > 0 && Objects.nonNull(deltaXList)) {
549	                    for (CT_CGTransform cgTransform : cgTransforms) {
550	                        int pos = cgTransform.getCodePosition();
551	                        int codeCount = cgTransform.getCodeCount();
552	                        if (i > pos && i < (pos + codeCount)) {
553	                            if (cgTransform.getGlyphs().size() < codeCount) {
554	                                skipPosition = true;
555	
556	                                skipCount++;
557	                            }
558	                            break;
559	                        }
560	                    }
561	                    int index = i - 1;
562	//                    boolean keepSameDX = false;
