564	                        index = deltaXList.size() - 1;
565	//                        keepSameDX = true;
566	                    }
567	                    double dx = Double.parseDouble(deltaXList.get(index));
568	                    if (dx != 0) {
569	                        if (hasCtm) {
570	                            Double[] ctms = ctm.toDouble();
