636	                if (skipPosition) {
637	                    text = "";
638	                }
639	                TextCodePoint textCodePoint = new TextCodePoint(converterDpi(realPos[0]), converterDpi(fixOriginToPdf ? (height - realPos[1]) : realPos[1]), text);
640	                textCodePointList.add(textCodePoint);
641	            }
642	        }//todo 先按textcode有值
643	        if (textCodePointList.size() > 0) {
644	            for (CT_CGTransform cgTransform : cgTransforms) {
645	                int pos = cgTransform.getCodePosition();
646	                int glyphCount = cgTransform.getGlyphCount();
