    58	        String[] arr = dataStr.split("\\s+");
    59	        LinkedList<OptVal> res = new LinkedList<>();
    60	        String opt = null;
    61	        List<String> values = new LinkedList<>();
    62	        for (String s : arr) {
    63	            if (s.isEmpty()) {
    64	                // 跳过split产生的空字符串（如前导空格导致的""）
    65	                continue;
    66	            }
    67	            switch (s) {
    68	                case "S":
    69	                case "M":
    70	                case "L":
    71	                case "Q":
    72	                case "B":
    73	                case "A":
    74	                case "C":
    75	                case "CM":
    76	                    if (opt != null) {
    77	                        res.add(new OptVal(opt, values));
    78	                    }
    79	                    values = new LinkedList<>();
    80	                    opt = s;
    81	                    break;
    82	                default:
    83	                    values.add(s);
    84	            }
    85	        }
    86	        if (opt != null) {
